import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))
    d = int(next(iterator))

    affected_set = set()
    for _ in range(m):
        affected_set.add(int(next(iterator)))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    if m == 0:
        print(n)
        return

    dist_from_affected = [-1] * (n + 1)
    queue = deque()

    for node in affected_set:
        dist_from_affected[node] = 0
        queue.append(node)

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist_from_affected[v] == -1:
                dist_from_affected[v] = dist_from_affected[u] + 1
                queue.append(v)

    max_dist_in_subtree = [0] * (n + 1)
    order = []
    parent = [0] * (n + 1)
    visited = [False] * (n + 1)

    root = list(affected_set)[0]
    stack = [root]
    visited[root] = True
    parent[root] = 0

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    for u in reversed(order):
        current_max = 0
        if u in affected_set:
            current_max = 0
        else:
            current_max = -1

        for v in adj[u]:
            if v != parent[u]:
                if max_dist_in_subtree[v] != -1:
                    current_max = max(current_max, max_dist_in_subtree[v] + 1)

        if current_max == -1:
            max_dist_in_subtree[u] = -1
        else:
            max_dist_in_subtree[u] = current_max

    max_dist_overall = [0] * (n + 1)

    for i, u in enumerate(order):
        p = parent[u]
        if i > 0:
            candidates = []
            if max_dist_in_subtree[u] != -1:
                candidates.append(max_dist_in_subtree[u])
            if p != 0 and max_dist_overall[p] != -1:
                candidates.append(max_dist_overall[p] + 1)
            if u in affected_set:
                candidates.append(0)

            if candidates:
                max_dist_overall[u] = max(candidates)
            else:
                max_dist_overall[u] = -1
        else:
            if u in affected_set:
                max_dist_overall[u] = 0
            else:
                max_dist_overall[u] = -1

    count = 0
    for i in range(1, n + 1):
        if max_dist_overall[i] != -1 and max_dist_overall[i] <= d:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
